// Regenerate with pier's palette (D154); source revisions: testdata/README.md.
//
//	node --experimental-strip-types coding/interactive/testdata/regenerate.mjs ./pi --write
//
// The golden file is generated by running the upstream custom editor with Node
// (coding/interactive/testdata/customeditor_golden.txt).

type customEditorCorpus struct {
	Render map[string]struct {
		Embed     bool    `json:"embed"`
		Indicator *string `json:"indicator"`
		Hidden    int     `json:"hidden"`
		Width     int     `json:"width"`
		Text      string  `json:"text"`
	} `json:"render"`
	Input map[string]struct {
		Text    string   `json:"text"`
		Inputs  []string `json:"inputs"`
		Actions []struct {
			Name string `json:"name"`
		} `json:"actions"`
		ExtensionShortcut string `json:"extensionShortcut"`
	} `json:"input"`
}

// editorTestHost is a minimal tui.EditorHost.
type editorTestHost struct{}

func (editorTestHost) Rows() int                { return 24 }
func (editorTestHost) RequestRender(force bool) {}

// TestCustomEditorAgainstUpstreamGolden replays the border renders and the
// input routing.
func TestCustomEditorAgainstUpstreamGolden(t *testing.T) {
	SetCustomThemesDir(t.TempDir())
	SetRegisteredThemes(nil)
	SetTrueColorSupport(true)
	SetStyleColorsEnabled(true)
	InitTheme("dark", false)

	golden := loadGoldenFile(t, "testdata/customeditor_golden.txt")
	data, err := os.ReadFile("testdata/customeditor_corpus.json")
	if err != nil {
		t.Fatalf("read corpus: %v", err)
	}
	corpus := customEditorCorpus{}
	if err := json.Unmarshal(data, &corpus); err != nil {
		t.Fatalf("parse corpus: %v", err)
	}

	keybindings := NewAppKeybindingsManager(nil, "")
	previous := tui.GetKeybindings()
	tui.SetKeybindings(keybindings.KeybindingsManager)
	defer tui.SetKeybindings(previous)

	theme := ActiveTheme()
	editorTheme := tui.EditorTheme{
		BorderColor: func(text string) string { return theme.Fg("border", text) },
	}

	for _, label := range sortedKeys(corpus.Render) {
		spec := corpus.Render[label]
		editor := NewCustomEditor(editorTestHost{}, editorTheme, keybindings, CustomEditorOptions{
			EmbedWorkingStatus: spec.Embed,
		})
		if spec.Indicator != nil {
			editor.SetWorkingStatusIndicator(NewStatusIndicator("working", editorTestHost{},
				func(text string) string { return theme.Fg("accent", text) },
				func(text string) string { return theme.Fg("muted", text) },
				*spec.Indicator, nil))
		}
		editor.SetText(spec.Text)
		checkGolden(t, golden, "render "+label+"@"+strconv.Itoa(spec.Width)+"/"+strconv.Itoa(spec.Hidden),
			editor.renderTopBorder(spec.Width, spec.Hidden))
	}

	for _, label := range sortedKeys(corpus.Input) {
		spec := corpus.Input[label]
		// The paste-image binding is platform-keyed (pasteImageKeys(windows)), and
		// this golden recorded the Unix key, so replaying it there asserts the
		// other labels without inventing a second recording.
		if runtime.GOOS == "windows" && label == "paste-image" {
			continue
		}
		editor := NewCustomEditor(editorTestHost{}, editorTheme, keybindings, CustomEditorOptions{})
		editor.SetText(spec.Text)
		var events []string
		editor.OnEscape = func() { events = append(events, "escape") }
		editor.OnCtrlD = func() { events = append(events, "ctrlD") }
		editor.OnPasteImage = func() { events = append(events, "pasteImage") }
		extensionShortcut := spec.ExtensionShortcut
		editor.OnExtensionShortcut = func(data string) bool {
			if extensionShortcut != "" && data == extensionShortcut {
				events = append(events, "ext:"+data)
				return true
			}
			return false
		}
		for _, action := range spec.Actions {
			actionName := action.Name
			editor.OnAction(tui.Keybinding(actionName), func() {
				events = append(events, "action:"+actionName)
			})
		}
		for _, input := range spec.Inputs {
			editor.HandleInput(input)
		}
		if events == nil {
			events = []string{}
		}
		checkGolden(t, golden, "input "+label, []any{events, editor.GetText()})
	}
}

// D417: a working label too wide for the editor border ends in an ellipsis
// instead of stopping at the word break the loader wrapped at. pi v1.5.0
// components/status-indicator.ts renderInBorder keeps the first wrapped line
// with no ellipsis; a label that fits renders the same as upstream's.
func TestWorkingStatusInBorderElidesOnNarrowScreens(t *testing.T) {
	SetCustomThemesDir(t.TempDir())
	SetRegisteredThemes(nil)
	InitTheme("dark", false)
	indicator := NewWorkingStatusIndicator(nil, "Working", nil, nil)
	indicator.Loader.SetElapsed(time.Now().Add(-76*time.Second), func(elapsed time.Duration) string {
		return workingElapsedLabel(elapsed, workingTokenCount{in: 3_400_000, out: 5600})
	})
	render := func(width int) string { return tui.StripTerminalSequences(indicator.RenderInBorder(width)) }
	if got := render(40); !strings.HasSuffix(got, " Working (1m 16s · ↑3.4M ↓5.6k)") {
		t.Fatalf("wide = %q", got)
	}
	for _, width := range []int{30, 18, 12} {
		got := render(width)
		if !strings.HasSuffix(got, "…") || strings.HasSuffix(got, " …") || tui.VisibleWidth(got) > width || !strings.Contains(got, " Working") {
			t.Errorf("width %d = %q", width, got)
		}
	}
	if got := render(18); !strings.HasSuffix(got, " Working (1m 16s…") {
		t.Fatalf("width 18 = %q", got)
	}
	// A cut that lands on a space puts the ellipsis right after the word.
	if got := render(11); !strings.HasSuffix(got, " Working…") {
		t.Fatalf("width 11 = %q", got)
	}
	// Where upstream keeps only the spinner, so does pier.
	if got := render(5); strings.Contains(got, "…") || strings.Contains(got, "W") {
		t.Fatalf("width 5 = %q", got)
	}
}

// staticAutocompleteProvider offers a fixed list, so the editor can open its
// autocomplete menu without a file system.
type staticAutocompleteProvider struct{ items []tui.AutocompleteItem }

func (staticAutocompleteProvider) TriggerCharacters() []string { return []string{"@"} }

func (p staticAutocompleteProvider) GetSuggestions(context.Context, []string, int, int, bool) *tui.AutocompleteSuggestions {
	return &tui.AutocompleteSuggestions{Prefix: "", Items: p.items}
}

func (staticAutocompleteProvider) ApplyCompletion(lines []string, cursorLine int, cursorCol int, _ tui.AutocompleteItem, _ string) tui.CompletionResult {
	return tui.CompletionResult{Lines: lines, CursorLine: cursorLine, CursorCol: cursorCol}
}

// Reference: pi v1.5.2 custom-editor.ts routes the selection page keys to the
// editor before any app action while the autocomplete menu is open, so a page
// key bound to an app action still pages the menu.
func TestCustomEditorPagesOpenAutocompleteBeforeAppActions(t *testing.T) {
	InitTheme("dark", false)
	keybindings := NewAppKeybindingsManager(map[string][]string{"app.suspend": {"pageDown"}}, "")
	editor := NewCustomEditor(editorTestHost{}, tui.EditorTheme{}, keybindings, CustomEditorOptions{})
	editor.SetAutocompleteProvider(staticAutocompleteProvider{items: []tui.AutocompleteItem{
		{Value: "alpha", Label: "alpha"},
		{Value: "beta", Label: "beta"},
	}})
	editor.HandleInput("@")
	if !editor.IsShowingAutocomplete() {
		t.Fatal("autocomplete did not open")
	}
	called := 0
	editor.OnAction("app.suspend", func() { called++ })
	editor.HandleInput("\x1b[6~") // pageDown
	if called != 0 {
		t.Fatalf("app action ran while the autocomplete was open")
	}
}

// Reference: pi v1.5.2 custom-editor.ts iterates actionHandlers in Map
// insertion order, so the first registered action wins when two are bound to
// the same key. The Go map has no order; the port must record it.
func TestCustomEditorRunsTheFirstRegisteredAction(t *testing.T) {
	InitTheme("dark", false)
	keybindings := NewAppKeybindingsManager(map[string][]string{
		"app.suspend": {"ctrl+y"},
		"app.clear":   {"ctrl+y"},
	}, "")
	editor := NewCustomEditor(editorTestHost{}, tui.EditorTheme{}, keybindings, CustomEditorOptions{})
	var ran []string
	editor.OnAction("app.suspend", func() { ran = append(ran, "suspend") })
	editor.OnAction("app.clear", func() { ran = append(ran, "clear") })
	editor.HandleInput("\x19")
	if len(ran) != 1 || ran[0] != "suspend" {
		t.Fatalf("handlers = %v, want the first registered action", ran)
	}
}

// D537, D538: the counts of scheduled loops and backgrounded calls sit in the
// editor's lower divider, just above the footer, which no longer carries them.
// The divider stays plain when there are none, and the counts read in full
// there: the divider is not cut to share the footer's width.
func TestEditorLowerDividerCountsBackgroundCalls(t *testing.T) {
	newRendererTestTheme(t)
	keybindings := NewAppKeybindingsManager(nil, "")
	editor := NewCustomEditor(editorTestHost{}, tui.EditorTheme{BorderColor: func(s string) string { return s }}, keybindings, CustomEditorOptions{})
	loops, running := 0, 0
	editor.LoopCount = func() int { return loops }
	editor.BackgroundCalls = func() int { return running }
	for _, tc := range []struct {
		loops, running int
		want           string
		width          int
	}{
		{0, 0, strings.Repeat("─", 50), 50},
		{0, 1, "── 1 background " + strings.Repeat("─", 34), 50},
		{0, 3, "── 3 background " + strings.Repeat("─", 34), 50},
		{2, 0, "── 2 loops scheduled " + strings.Repeat("─", 29), 50},
		{1, 1, "── 1 loop scheduled · 1 background " + strings.Repeat("─", 15), 50},
		// Too narrow for the label: the plain divider, never a cut one.
		{1, 1, strings.Repeat("─", 30), 30},
	} {
		loops, running = tc.loops, tc.running
		lines := editor.Render(tc.width)
		if got := stripAnsiEscapes(lines[len(lines)-1]); got != tc.want {
			t.Fatalf("%d running: lower divider = %q, want %q", tc.running, got, tc.want)
		}
	}
}
